   151→/// Calculate how much market coin should be minted
   152→public(package) fun mint_ctokens<MarketType, CoinType>(
   153→    self: &mut Reserve<MarketType>,
   154→    coin: Coin<CoinType>,
   155→): Balance<CToken<MarketType, CoinType>> {
   156→    let collateral_amount = coin.value();
   157→    assert!(collateral_amount > 0, error::reserve_zero_coin_not_allowed());
   158→
   159→    // TODO: ensure small truncated number will not impact accuracy
   160→    let mint_amount = float::int_div(collateral_amount, self.exchange_rate());
   161→
   162→    self.deposit_underlying(coin);
   163→    self.increase_ctoken_supply(mint_amount)
   164→}
   165→
   166→public(package) fun liquidate_ctokens<MarketType, CoinType>(
   167→    self: &mut Reserve<MarketType>,
   168→    ctokens: Coin<CToken<MarketType, CoinType>>,
   169→    liq_revenue_factor: Decimal,
   170→): Balance<CoinType> {
   171→    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());
   172→
   173→    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());
   174→
   175→    let protocol_seize_amount = liq_revenue_factor.int_mul(redeem_collateral_amount);
   176→    let liquidator_seize_amount = redeem_collateral_amount - protocol_seize_amount;
   177→
   178→    self.cash_reserve = self.cash_reserve.add(math::float::from(protocol_seize_amount));
   179→
   180→    self.decrease_ctoken_supply(ctokens.into_balance());
   181→    self.withdraw_underlying(liquidator_seize_amount)
   182→}
   183→
   184→public(package) fun burn_ctokens<MarketType, CoinType>(
   185→    self: &mut Reserve<MarketType>,
   186→    ctokens: Coin<CToken<MarketType, CoinType>>,
   187→): Balance<CoinType> {
   188→    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());
   189→
   190→    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());
   191→
   192→    self.decrease_ctoken_supply(ctokens.into_balance());
   193→    self.withdraw_underlying(redeem_collateral_amount)
   194→}
