     1→/// fixed point float representation. 18 decimal places are kept.
     2→module math::float;
     3→
     4→use math::math_error;
     5→
     6→const U64_MAX_256: u256 = 18446744073709551615u256;
     7→// VALUE_MAX_256 = U64_MAX_256 * WAD
     8→const VALUE_MAX_256: u256 = 18446744073709551615000000000000000000u256;
     9→const WAD: u256 = 1000000000000000000;
    10→
    11→public struct Decimal has copy, drop, store {
    12→    value: u256,
    13→}
    14→
    15→public fun zero(): Decimal { Decimal { value: 0 } }
    16→
    17→public fun one(): Decimal { from(1) }
    18→
    19→public fun from(v: u64): Decimal { Decimal { value: (v as u256) * WAD } }
    20→
    21→public fun from_quotient(numerator: u64, denominator: u64): Decimal {
    22→    Decimal {
    23→        value: ensure_decimal_value_safe((numerator as u256) * WAD / (denominator as u256)),
    24→    }
    25→}
    26→
    27→public fun is_zero(a: &Decimal): bool {
    28→    a.value == 0
    29→}
    30→
    31→public fun add(a: Decimal, b: Decimal): Decimal {
    32→    Decimal {
    33→        value: ensure_decimal_value_safe(a.value + b.value),
    34→    }
    35→}
    36→
    37→public fun add_u64(a: &Decimal, b: u64): Decimal {
    38→    let value = b as u256 * WAD;
    39→    Decimal {
    40→        value: ensure_decimal_value_safe(a.value + value),
    41→    }
    42→}
    43→
    44→public fun sub(a: Decimal, b: Decimal): Decimal {
    45→    Decimal {
    46→        value: a.value - b.value,
    47→    }
    48→}
    49→
    50→public fun sub_u64(a: Decimal, b: u64): Decimal {
    51→    let value = from(b);
    52→    sub(a, value)
    53→}
    54→
    55→public fun saturating_sub(a: Decimal, b: Decimal): Decimal {
    56→    if (a.value < b.value) {
    57→        Decimal { value: 0 }
    58→    } else {
    59→        Decimal { value: a.value - b.value }
    60→    }
    61→}
    62→
    63→public fun int_mul(a: Decimal, b: u64): u64 {
    64→    safe_from_u256((a.value * (b as u256)) / WAD)
    65→}
    66→
    67→/// An integer divide this decimal: b / a = b / (a.value / WAD) = b * WAD / a.value
    68→public fun int_div(b: u64, a: Decimal): u64 {
    69→    safe_from_u256(WAD * (b as u256) / a.value)
    70→}
    71→
    72→public fun mul(a: Decimal, b: Decimal): Decimal {
    73→    Decimal {
    74→        value: ensure_decimal_value_safe((a.value * b.value) / WAD),
    75→    }
    76→}
    77→
    78→public fun mul_u64(a: Decimal, b: u64): Decimal {
    79→    let value = from(b);
    80→    mul(a, value)
    81→}
    82→
    83→public fun div(a: Decimal, b: Decimal): Decimal {
    84→    Decimal {
    85→        value: ensure_decimal_value_safe((a.value * WAD) / b.value),
    86→    }
    87→}
    88→
    89→public fun div_u64(a: Decimal, b: u64): Decimal {
    90→    let value = from(b);
    91→    div(a, value)
    92→}
    93→
    94→public fun floor(a: Decimal): u64 {
    95→    safe_from_u256(a.value / WAD) as u64
    96→}
    97→
    98→public fun ceil(a: Decimal): u64 {
    99→    safe_from_u256((a.value + WAD - 1) / WAD) as u64
   100→}
   101→
   102→public fun eq(a: Decimal, b: Decimal): bool {
   103→    a.value == b.value
   104→}
   105→
   106→public fun ge(a: Decimal, b: Decimal): bool {
   107→    a.value >= b.value
